<?php
function pusher_default_config():array{
 global $env;
 $file=__DIR__.'/pusher-defaults.php';$d=is_file($file)?require $file:[];
 if(!is_array($d))$d=[];
 foreach(['app_id'=>'PUSHER_APP_ID','key'=>'PUSHER_APP_KEY','secret'=>'PUSHER_APP_SECRET','cluster'=>'PUSHER_APP_CLUSTER','enabled'=>'PUSHER_ENABLED']as $field=>$key)if(isset($env[$key]))$d[$field]=$env[$key];
 $d=array_replace(['app_id'=>'','key'=>'','secret'=>'','cluster'=>'ap2','enabled'=>false],$d);
 $d['enabled']=filter_var($d['enabled'],FILTER_VALIDATE_BOOLEAN)&&$d['app_id']!==''&&$d['key']!==''&&$d['secret']!=='';
 return $d;
}
function studio_defaults():array{$pusher=pusher_default_config();return [
 'branding'=>['name'=>'Lifestyle Store','tagline_en'=>'ROOTED IN EVERYDAY','tagline_bn'=>'প্রতিদিনে শিকড়ের ছোঁয়া','logo_light'=>'/assets/round-mark.png','logo_dark'=>'/assets/round-mark-dark.png','favicon'=>'/assets/round-favicon.png','social_image'=>'/assets/hero.jpg','title_en'=>'Lifestyle Store — Find your everyday','title_bn'=>'Lifestyle Store — প্রতিদিনের প্রিয় খুঁজে নিন','description_en'=>'Thoughtful threads. Beautiful everyday. Shop fashion, home and heritage, with easy cash on delivery.','description_bn'=>'যত্নের বুনন। সুন্দর প্রতিদিন। ফ্যাশন ও ঘরের পণ্য কিনুন সহজ ক্যাশ অন ডেলিভারিতে।','robots'=>'index,follow'],
 'design'=>['body_font'=>'dm','heading_font'=>'playfair','bn_body_font'=>'anek','bn_heading_font'=>'tiro','body_size'=>14,'heading_size'=>42,'accent'=>'#344d3c','text'=>'#29332b','muted'=>'#68715f','background'=>'#f8f6f0','surface'=>'#ffffff','dark_background'=>'#17201b','dark_text'=>'#e4e8df','button_radius'=>4,'rules'=>[]],
 'carousel'=>['autoplay'=>true,'interval'=>6000,'pause_hover'=>true],
 'realtime'=>['enabled'=>true,'poll_seconds'=>10,'pusher_enabled'=>$pusher['enabled'],'browser_notifications'=>true,'new_order'=>true,'order_status'=>true,'site_updates'=>true,'pusher_key'=>$pusher['key'],'pusher_cluster'=>$pusher['cluster']],
 'texts'=>[]
];}
function studio_value(string $k):array{
 $defaults=studio_defaults()[$k]??[];$v=json_decode(setting('studio_'.$k,'{}'),true);if(!is_array($v))return $defaults;
 // An untouched legacy empty form should inherit the supplied defaults; explicit saved credentials/settings win.
 if($k==='realtime'&&empty($v['pusher_key'])){$private=json_decode(setting('private_pusher','{}'),true)?:[];if(empty($private['app_id'])&&empty($private['secret']))foreach(['pusher_enabled','pusher_key','pusher_cluster']as $field)unset($v[$field]);}
 return array_replace($defaults,$v);
}
function media_path(string $v,bool $empty=true):string{global $root;if($v===''&&$empty)return '';if($v==='/assets/favicon.svg')return $v;if(!preg_match('#^/assets/(?:uploads/)?[a-zA-Z0-9_-]+\.(?:jpg|jpeg|png|webp)$#',$v)||!is_file($root.'/public'.$v))throw new RuntimeException('Choose a valid image from the media library.');return $v;}
function studio_public():array{return ['branding'=>studio_value('branding'),'design'=>studio_value('design'),'carousel'=>studio_value('carousel'),'realtime'=>studio_value('realtime'),'texts'=>array_values(json_decode(setting('studio_texts','[]'),true)?:[]),'slides'=>query('SELECT * FROM hero_slides WHERE active=1 ORDER BY position,id')->fetchAll(),'revision'=>(int)setting('site_revision','1')];}
function secret_key():string{global $root;$file=app_storage_path('.encryption-key');$lock=fopen(app_storage_path('.key-init.lock'),'c');if(!$lock||!flock($lock,LOCK_EX))throw new RuntimeException('Cannot initialize credential encryption.');try{if(!is_file($file)){if(file_put_contents($file,random_bytes(SODIUM_CRYPTO_SECRETBOX_KEYBYTES),LOCK_EX)===false)throw new RuntimeException('Cannot save credential encryption key.');chmod($file,0600);}$key=file_get_contents($file);if(strlen($key)!==SODIUM_CRYPTO_SECRETBOX_KEYBYTES)throw new RuntimeException('Credential encryption key is invalid. Restore the protected backup key.');return $key;}finally{flock($lock,LOCK_UN);fclose($lock);}}
function secret_encrypt(string $s):string{$nonce=random_bytes(SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);return base64_encode($nonce.sodium_crypto_secretbox($s,$nonce,secret_key()));}
function secret_decrypt(string $s):string{if(!$s)return '';$s=base64_decode($s,true);if(!$s||strlen($s)<=SODIUM_CRYPTO_SECRETBOX_NONCEBYTES)return '';return sodium_crypto_secretbox_open(substr($s,SODIUM_CRYPTO_SECRETBOX_NONCEBYTES),substr($s,0,SODIUM_CRYPTO_SECRETBOX_NONCEBYTES),secret_key())?:'';}
function pusher_private():array{
 $saved=json_decode(setting('private_pusher','{}'),true)?:[];
 if(!empty($saved['app_id'])||array_key_exists('secret',$saved))return $saved;
 $d=pusher_default_config();return ['app_id'=>$d['app_id'],'secret'=>$d['secret']!==''?secret_encrypt($d['secret']):''];
}
function pusher_publish(string $channel,array $payload):array{$public=studio_value('realtime');$private=pusher_private();if(!$public['pusher_enabled'])return ['ok'=>false,'reason'=>'Pusher is disabled. Polling is available.'];$secret=secret_decrypt($private['secret']??'');$app=$private['app_id']??'';$key=$public['pusher_key'];$cluster=$public['pusher_cluster'];if(!$secret||!$app||!$key)return ['ok'=>false,'reason'=>'Pusher credentials are incomplete.'];$body=json_encode(['name'=>'bonon-event','channels'=>[$channel],'data'=>json_encode($payload,JSON_UNESCAPED_UNICODE)],JSON_UNESCAPED_SLASHES);$path='/apps/'.$app.'/events';$params=['auth_key'=>$key,'auth_timestamp'=>time(),'auth_version'=>'1.0','body_md5'=>md5($body)];ksort($params);$qs=http_build_query($params);$sig=hash_hmac('sha256',"POST\n$path\n$qs",$secret);$url='https://api-'.$cluster.'.pusher.com'.$path.'?'.$qs.'&auth_signature='.$sig;$ctx=stream_context_create(['http'=>['method'=>'POST','header'=>"Content-Type: application/json\r\n",'content'=>$body,'timeout'=>3,'ignore_errors'=>true]]);$res=@file_get_contents($url,false,$ctx);$status=0;foreach($http_response_header??[] as $h)if(preg_match('#^HTTP/\S+ (\d+)#',$h,$m))$status=(int)$m[1];$ok=$status>=200&&$status<300;set_setting('private_pusher_health',json_encode(['ok'=>$ok,'status'=>$status,'time'=>date(DATE_ATOM)]));return ['ok'=>$ok,'status'=>$status,'reason'=>$ok?'Pusher accepted the event.':'Pusher did not accept the event. Check credentials and cluster.'];}
function emit_event(string $type,string $audience,array $payload=[],?int $uid=null):void{$cfg=studio_value('realtime');query('INSERT INTO realtime_events(type,audience,user_id,payload) VALUES(?,?,?,?)',[$type,$audience,$uid,json_encode($payload,JSON_UNESCAPED_UNICODE)]);global $db;$id=(int)$db->lastInsertId();if(!$cfg['enabled'])return;if($type==='new-order'&&!$cfg['new_order'])return;if($type==='order-status'&&!$cfg['order_status'])return;if($type==='site-update'&&!$cfg['site_updates'])return;$channel=$audience==='admin'?'private-bonon-admin':($audience==='user'?'private-bonon-user-'.$uid:'bonon-public');if($cfg['pusher_enabled'])pusher_publish($channel,['id'=>$id,'type'=>$type,'payload'=>$payload]);}
function site_changed(string $kind='content'):void{query("INSERT INTO settings(`key`,value) VALUES('site_revision','2') ON DUPLICATE KEY UPDATE value=CAST(value AS UNSIGNED)+1");emit_event('site-update','public',['kind'=>$kind,'revision'=>(int)setting('site_revision')]);}
function event_scope(?array $u):array{if(!$u)return ["audience='public'",[]];if($u['role']==='admin')return ["(audience='public' OR audience='admin' OR (audience='user' AND user_id=?))",[$u['id']]];return ["(audience='public' OR (audience='user' AND user_id=?))",[$u['id']]];}
function clean_style(array $s):array{$out=[];foreach(['size'=>[8,120],'mobile_size'=>[8,80],'letter_spacing'=>[-3,12],'line_height'=>[1,3],'radius'=>[0,50]] as $k=>$range)if(isset($s[$k])&&$s[$k]!==''){if(!is_numeric($s[$k]))throw new RuntimeException('Use a valid typography number.');$out[$k]=max($range[0],min($range[1],(float)$s[$k]));}foreach(['color','background']as $k)if(!empty($s[$k])){if(!preg_match('/^#[a-f0-9]{6}$/i',$s[$k]))throw new RuntimeException('Use a six-digit hex color.');$out[$k]=$s[$k];}if(isset($s['weight'])&&$s['weight']!==''){$v=(string)$s['weight'];if(!in_array($v,['300','400','500','600','700','800']))throw new RuntimeException('Invalid font weight.');$out['weight']=$v;}if(!empty($s['font'])){if(!in_array($s['font'],['dm','manrope','playfair','anek','tiro','noto']))throw new RuntimeException('Invalid font.');$out['font']=$s['font'];}if(isset($s['italic']))$out['italic']=(bool)$s['italic'];return $out;}
function clean_selector(string $s):string{if(strlen($s)>200||!preg_match('/^[a-zA-Z0-9.#_\-\s>:(),\[\]="\']*$/',$s))throw new RuntimeException('Use a valid CSS selector without custom code.');return trim($s);}
